func TestTieredPlans(t *testing.T) {
	e := apitest.New(t)
	ten, twenty := int64(10), int64(20)
	var p struct {
		store.Plan
		Price string `json:"price"`
	}
	tiers := []map[string]any{
		{"up_to": 10, "unit_amount": "1.00"},
		{"up_to": 20, "unit_amount": "0.80", "flat_amount": "5.00"},
		{"up_to": nil, "unit_amount": "0.50", "flat_amount": "10"},
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "API", "currency": "USD", "interval": "month",
		"usage_type": "metered", "tiers_mode": "volume", "tiers": tiers}, &p)
	want := []store.Tier{{UpTo: &ten, UnitAmount: 100}, {UpTo: &twenty, UnitAmount: 80, FlatAmount: 500}, {UnitAmount: 50, FlatAmount: 1000}}
	if p.TiersMode != store.Volume || !reflect.DeepEqual(p.Tiers, want) || p.UnitAmount != 0 {
		t.Fatalf("plan = %+v", p)
	}

	tier := func(upTo any, unit string) map[string]any { return map[string]any{"up_to": upTo, "unit_amount": unit} }
	plan := func(usage, mode string, tiers ...map[string]any) map[string]any {
		body := map[string]any{"name": "X", "currency": "USD", "interval": "month", "usage_type": usage, "tiers_mode": mode}
		if tiers != nil {
			body["tiers"] = tiers
		}
		return body
	}
	for _, bad := range []map[string]any{
		plan("metered", "volume"),                                                           // a mode without tiers
		plan("metered", "", tier(nil, "1")),                                                 // tiers without a mode
		plan("metered", "stairs", tier(nil, "1")),                                           // an unknown mode
		plan("metered", "graduated", []map[string]any{}...),                                 // no tiers at all
		plan("metered", "graduated", tier(20, "1"), tier(10, "1"), tier(nil, "1")),          // not ascending
		plan("metered", "graduated", tier(10, "1"), tier(10, "1"), tier(nil, "1")),          // repeated up_to
		plan("metered", "graduated", tier(0, "1"), tier(nil, "1")),                          // zero up_to
		plan("metered", "graduated", tier(10, "1")),                                         // the last tier has a limit
		plan("metered", "graduated", tier(nil, "1"), tier(20, "1")),                         // an unlimited tier before the last
		plan("metered", "graduated", tier(10.5, "1"), tier(nil, "1")),                       // a fractional up_to
		plan("metered", "graduated", tier("10", "1"), tier(nil, "1")),                       // an up_to that is a string
		plan("metered", "graduated", tier(10, "-1"), tier(nil, "1")),                        // a negative unit amount
		plan("metered", "graduated", map[string]any{"up_to": 10, "unit_amount": "1", "flat_amount": "-2"}, tier(nil, "1")),
		plan("metered", "graduated", map[string]any{"up_to": 10, "flat_amount": "1"}, tier(nil, "1")), // no unit amount
		plan("metered", "graduated", tier(10, "abc"), tier(nil, "1")),
		plan("licensed", "volume", tier(nil, "1")), // tiers on a licensed plan
		plan("", "volume", tier(nil, "1")),         // licensed by default
	} {
		bad["name"] = "X"
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_tiers" {
			t.Fatalf("%v: %s", bad, r)
		}
	}
}

