54	// parseTiers reads tiers in major units into tiers in minor units. Any error wraps store.ErrInvalidTiers.
55	func parseTiers(in []tierIn, c money.Currency) ([]store.Tier, error) {
56		tiers := make([]store.Tier, 0, len(in))
57		for _, t := range in {
58			var upTo *int64
59			if len(t.UpTo) > 0 && string(t.UpTo) != "null" {
60				n, err := strconv.ParseInt(string(t.UpTo), 10, 64)
61				if err != nil {
62					return nil, fmt.Errorf("%w: up_to is a whole number or null", store.ErrInvalidTiers)
63				}
64				upTo = &n
65			}
66			unitStr, err := majorString(t.UnitAmount)
67			if err != nil {
68				return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
69			}
70			unit, err := money.ParseMajor(unitStr, c)
71			if err != nil {
72				return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
73			}
74			flatStr, err := majorString(t.FlatAmount)
75			if err != nil {
76				return nil, fmt.Errorf("%w: flat_amount: %v", store.ErrInvalidTiers, err)
77			}
78			var flat int64
79			if flatStr != "" {
80				if flat, err = money.ParseMajor(flatStr, c); err != nil {
81					return nil, fmt.Errorf("%w: flat_amount: %v", store.ErrInvalidTiers, err)
82				}
83			}
84			tiers = append(tiers, store.Tier{UpTo: upTo, UnitAmount: unit, FlatAmount: flat})
85		}
86		return tiers, nil
87	}
