62					return nil, fmt.Errorf("%w: up_to is a whole number or null", store.ErrInvalidTiers)
63				}
64				upTo = &n
65			}
66			unitStr, err := majorString(t.UnitAmount)
67			if err != nil {
68				return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
69			}
70			unit, err := money.ParseMajor(unitStr, c)
71			if err != nil {
72				return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
73			}
