89	// parseTiersBody reads a request's tiers_mode and tiers. Any error wraps store.ErrInvalidTiers.
90	func parseTiersBody(rawMode, rawTiers json.RawMessage, c money.Currency) (store.TiersMode, []store.Tier, error) {
91		var mode store.TiersMode
92		if len(rawMode) > 0 {
93			if err := json.Unmarshal(rawMode, &mode); err != nil {
94				return "", nil, fmt.Errorf("%w: tiers_mode is a string", store.ErrInvalidTiers)
95			}
96		}
97		var in []tierIn
98		if len(rawTiers) > 0 {
99			if err := json.Unmarshal(rawTiers, &in); err != nil {
100				return "", nil, fmt.Errorf("%w: tiers is a list of tiers", store.ErrInvalidTiers)
101			}
102		}
103		tiers, err := parseTiers(in, c)
104		if err != nil {
105			return "", nil, err
106		}
107		return mode, tiers, nil
108	}
