110	// wantsTiers reports whether a request asks for tiers: a tiers list, or a tiers_mode that is not empty.
111	func wantsTiers(rawMode, rawTiers json.RawMessage) bool {
112		hasTiers := len(rawTiers) > 0 && string(rawTiers) != "null"
113		hasMode := len(rawMode) > 0 && string(rawMode) != "null" && string(rawMode) != `""`
114		return hasTiers || hasMode
