117	// createPlan takes the price in major units, as a string ("12.50"), the way people type it. A metered plan may have tiers
118	// instead of a price; a price given with tiers is ignored.
119	func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
120		var in struct {
121			Name      string          `json:"name"`
122			Currency  money.Currency  `json:"currency"`
123			Price     string          `json:"price"`
124			Interval  store.Interval  `json:"interval"`
125			UsageType store.UsageType `json:"usage_type"`
126			TrialDays int             `json:"trial_days"`
127			TiersMode json.RawMessage `json:"tiers_mode"`
128			Tiers     json.RawMessage `json:"tiers"`
129		}
130		if !decode(w, r, &in) {
131			return
132		}
133		pl := store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, Interval: in.Interval, UsageType: in.UsageType,
134			TrialDays: in.TrialDays}
135		if wantsTiers(in.TiersMode, in.Tiers) {
136			mode, tiers, err := parseTiersBody(in.TiersMode, in.Tiers, in.Currency)
137			if err != nil {
138				s.storeError(w, err)
139				return
140			}
141			pl.TiersMode, pl.Tiers = mode, tiers
142		} else {
143			amount, err := money.ParseMajor(in.Price, in.Currency)
144			if err != nil {
145				if errors.Is(err, money.ErrInvalidAmount) {
146					writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
147					return
148				}
149				s.storeError(w, err)
150				return
151			}
152			pl.UnitAmount = amount
153		}
154		pl, err := s.store.CreatePlan(pl, s.clock.Now())
155		if err != nil {
156			s.storeError(w, err)
157			return
158		}
159		writeJSON(w, http.StatusCreated, viewPlan(pl))
160	}
